1	/*
2	 * solver.cpp — Backtracking SLD resolution engine.
3	 * JPL rules: no C recursion, bounded stacks, no post-init malloc.
4	 */
5	
6	#include "../include/solver.hpp"
7	#include "../include/builtins.hpp"
8	#include "../include/log.hpp"
9	#include <cstring>
10	#include <cassert>
11	
12	/* ---- Internal frame types ------------------------------------------------- */
13	
14	struct GoalStack {
15	    TermRef  goals[GOAL_STACK_CAPACITY];
16	    uint32_t top = 0U;
17	};
18	
19	struct ChoicePoint {
20	    uint32_t clause_idx;
21	    uint32_t clause_end;
22	    TermRef  goal;
23	    uint32_t trail_mark;
24	    uint32_t goal_top;
25	};
26	
27	struct ChoiceStack {
28	    ChoicePoint items[CHOICE_STACK_CAPACITY];
29	    uint32_t    top = 0U;
30	};
31	
32	/* ---- Variable rename map -------------------------------------------------- */
33	
34	constexpr uint32_t RENAME_MAP_CAP = VAR_REGISTRY_CAPACITY;
35	
36	struct RenameMap {
37	    VarId    old_id[RENAME_MAP_CAP];
38	    VarId    new_id[RENAME_MAP_CAP];
39	    uint32_t count = 0U;
40	};
41	
42	static VarId rename_lookup(const RenameMap *rm, VarId old)
43	{
44	    for (uint32_t i = 0U; i < rm->count; ++i) {
45	        if (rm->old_id[i] == old) { return rm->new_id[i]; }
46	    }
47	    return VAR_ID_INVALID;
48	}
49	
50	/* rename_term — deep-copy a clause term into env->arena with fresh VarIds. */
51	static TermRef rename_term(TermRef ref, const TermArena *arena,
52	                            SolverEnv *env, RenameMap *rm,
53	                            const AtomTable *)
54	{
55	    for (uint32_t step = 0U; step < TERM_ARENA_CAPACITY; ++step) {
56	        const Term *t = term_get(arena, ref);
57	        if (t == nullptr) { return TERM_REF_INVALID; }
58	
59	        switch (t->kind) {
60	            case TERM_KIND_ATOM:
61	                return term_make_atom(env->arena, t->data.atom_id);
62	            case TERM_KIND_INT:
63	                return term_make_int(env->arena, t->data.int_val);
64	            case TERM_KIND_VAR: {
65	                const VarId old   = t->data.var.var_id;
66	                VarId       fresh = rename_lookup(rm, old);
67	                if (fresh == VAR_ID_INVALID) {
68	                    const char *vname = t->data.var.name;
69	                    fresh = var_alloc(env->vars, vname[0] ? vname : "_");
70	                    if (fresh == VAR_ID_INVALID) { return TERM_REF_INVALID; }
71	                    if (rm->count < RENAME_MAP_CAP) {
72	                        rm->old_id[rm->count] = old;
73	                        rm->new_id[rm->count] = fresh;
74	                        rm->count++;
75	                    }
76	                }
77	                return term_make_var(env->arena, fresh, t->data.var.name);
78	            }
79	            case TERM_KIND_COMPOUND: {
80	                TermRef        new_args[TERM_MAX_ARITY];
81	                const uint8_t  arity = t->data.compound.arity;
82	                for (uint8_t i = 0U; i < arity; ++i) {
83	                    new_args[i] = rename_term(term_arg(arena, ref, i),
84	                                              arena, env, rm, nullptr);
85	                    if (new_args[i] == TERM_REF_INVALID) { return TERM_REF_INVALID; }
86	                }
87	                return term_make_compound(env->arena, t->data.compound.functor,
88	                                          arity, new_args);
89	            }
90	            default:
91	                return TERM_REF_INVALID;
92	        }
93	        break;
94	    }
95	    return TERM_REF_INVALID;
96	}
97	
98	/* ---- GoalStack helpers ---------------------------------------------------- */
99	
100	static int gs_push(GoalStack *gs, TermRef g)
101	{
102	    if (gs->top >= GOAL_STACK_CAPACITY) { return -1; }
103	    gs->goals[gs->top++] = g;
104	    return 0;
105	}
106	
107	static TermRef gs_pop(GoalStack *gs)
108	{
109	    if (gs->top == 0U) { return TERM_REF_INVALID; }
110	    return gs->goals[--gs->top];
111	}
112	
113	/* ---- Public API ----------------------------------------------------------- */
114	
115	int solver_env_init(SolverEnv *env,
116	                    TermArena *arena, TermArena *clause_arena,
117	                    VarRegistry *vars, VarRegistry *clause_vars,
118	                    AtomTable *atoms, Database *db)
119	{
120	    if (!env || !arena || !clause_arena || !vars || !clause_vars || !atoms || !db) {
121	        return -1;
122	    }
123	    memset(env, 0, sizeof(SolverEnv));
124	    env->arena        = arena;
125	    env->clause_arena = clause_arena;
126	    env->vars         = vars;
127	    env->clause_vars  = clause_vars;
128	    env->atoms        = atoms;
129	    env->db           = db;
130	    trail_init(&env->trail);
131	    return 0;
132	}
133	
134	uint32_t solve(SolverEnv *env, const TermRef *goals, uint32_t goal_count,
135	               SolutionCallback cb, void *userdata)
136	{
137	    if (!env || !goals || goal_count == 0U || !cb) { return 0U; }
138	
139	    GoalStack   gs;
140	    ChoiceStack cs;
141	    memset(&gs, 0, sizeof(GoalStack));
142	    memset(&cs, 0, sizeof(ChoiceStack));
143	
144	    uint32_t solutions = 0U;
145	
146	    for (uint32_t gi = goal_count; gi > 0U; --gi) {
147	        if (gs_push(&gs, goals[gi - 1U]) < 0) { return 0U; }
148	    }
149	
150	    /* label targets — using C++ style with a flag to avoid cross-init goto */
151	    bool do_backtrack = false;
152	
153	    for (uint32_t iter = 0U; iter < 10000000U; ++iter) {
154	
155	        if (do_backtrack) {
156	            do_backtrack = false;
157	            goto backtrack;
158	        }
159	
160	        /* SUCCESS */
161	        if (gs.top == 0U) {
162	            solutions++;
163	            if (cb(env, goals, goal_count, userdata) == SOLVE_STOP) {
164	                return solutions;
165	            }
166	            if (cs.top == 0U) { return solutions; }
167	            goto backtrack;
168	        }
169	
170	        /* pop and process next goal */
171	        {
172	            const TermRef  goal    = gs_pop(&gs);
173	            const TermRef  dgoal   = deref(goal, env->arena, env->vars);
174	            const Term    *gt      = term_get(env->arena, dgoal);
175	            AtomId         functor = ATOM_ID_INVALID;
176	            uint8_t        arity   = 0U;
177	
178	            if (gt == nullptr)                  { goto backtrack; }
179	            if (gt->kind == TERM_KIND_ATOM)     { functor = gt->data.atom_id; arity = 0U; }
180	            else if (gt->kind == TERM_KIND_COMPOUND) {
181	                functor = gt->data.compound.functor;
182	                arity   = gt->data.compound.arity;
183	            } else { goto backtrack; }
184	
185	            /* built-in? */
186	            {
187	                BuiltinFn bf = builtin_lookup(functor, arity, env->atoms);
188	                if (bf != nullptr) {
189	                    switch (bf(dgoal, env)) {
190	                        case BUILTIN_SUCCEED: continue;
191	                        case BUILTIN_FAIL:    goto backtrack;
192	                        case BUILTIN_CUT:     cs.top = 0U; continue;
193	                        case BUILTIN_ERROR:   return solutions;
194	                    }
195	                }
196	            }
197	
198	            /* user-defined clause lookup */
199	            {
200	                const PredEntry *pred = db_get_pred(env->db, functor, arity);
201	                VLOG_SUBSYS("SOLVE", "goal functor=%u arity=%u pred=%s count=%u",
202	                            functor, arity,
203	                            pred ? atom_spelling(env->atoms, functor) : "?NONE",
204	                            pred ? pred->count : 0U);
205	                if (pred == nullptr || pred->count == 0U) {
206	                    VLOG_SUBSYS("SOLVE", "%s", "no clauses -> backtrack");
207	                    goto backtrack;
208	                }
209	
210	                if (pred->count > 1U && cs.top < CHOICE_STACK_CAPACITY) {
211	                    ChoicePoint *cp  = &cs.items[cs.top++];
212	                    cp->clause_idx   = pred->first + 1U;
213	                    cp->clause_end   = pred->first + pred->count;
214	                    cp->goal         = goal;
215	                    cp->trail_mark   = trail_mark(&env->trail);
216	                    cp->goal_top     = gs.top;
217	                }
218	
219	                {
220	                    const StoredClause *sc = db_get_clause(env->db, pred->first);
221	                    if (sc == nullptr) { goto backtrack; }
222	
223	                    RenameMap rm;
224	                    memset(&rm, 0, sizeof(RenameMap));
225	                    const uint32_t mark = trail_mark(&env->trail);
226	
227	                    const TermRef fresh_head = rename_term(
228	                        sc->head, env->clause_arena, env, &rm, env->atoms);
229	                    if (fresh_head == TERM_REF_INVALID) { goto backtrack; }
230	
231	                    VLOG_SUBSYS("SOLVE", "trying clause head ref=%u", sc->head);
232	                    if (!unify(dgoal, fresh_head, env->arena, env->vars, &env->trail)) {
233	                        VLOG_SUBSYS("SOLVE", "%s", "unify failed -> backtrack");
234	                        trail_undo(&env->trail, env->vars, mark);
235	                        goto backtrack;
236	                    }
237	                    VLOG_SUBSYS("SOLVE", "unified ok, body_len=%u", sc->body_len);
238	
239	                    for (uint32_t bi = sc->body_len; bi > 0U; --bi) {
240	                        const TermRef fresh_body = rename_term(
241	                            sc->body[bi - 1U], env->clause_arena, env, &rm, env->atoms);
242	                        if (fresh_body == TERM_REF_INVALID ||
243	                            gs_push(&gs, fresh_body) < 0) {
244	                            trail_undo(&env->trail, env->vars, mark);
245	                            goto backtrack;
246	                        }
247	                    }
248	                }
249	            }
250	            continue;
251	        }
252	
253	        backtrack:
254	        {
255	            if (cs.top == 0U) { return solutions; }
256	
257	            ChoicePoint *cp = &cs.items[cs.top - 1U];
258	            trail_undo(&env->trail, env->vars, cp->trail_mark);
259	            gs.top = cp->goal_top;
260	
261	            if (cp->clause_idx >= cp->clause_end) { cs.top--; goto backtrack; }
262	
263	            {
264	                const StoredClause *sc = db_get_clause(env->db, cp->clause_idx);
265	                const TermRef dgoal = deref(cp->goal, env->arena, env->vars);
266	
267	                cp->clause_idx++;
268	                if (cp->clause_idx >= cp->clause_end) { cs.top--; }
269	
270	                if (sc == nullptr) { goto backtrack; }
271	
272	                RenameMap rm;
273	                memset(&rm, 0, sizeof(RenameMap));
274	                const uint32_t mark = trail_mark(&env->trail);
275	
276	                const TermRef fresh_head = rename_term(
277	                    sc->head, env->clause_arena, env, &rm, env->atoms);
278	                if (fresh_head == TERM_REF_INVALID) { goto backtrack; }
279	
280	                if (!unify(dgoal, fresh_head, env->arena, env->vars, &env->trail)) {
281	                    trail_undo(&env->trail, env->vars, mark);
282	                    goto backtrack;
283	                }
284	
285	                for (uint32_t bi = sc->body_len; bi > 0U; --bi) {
286	                    const TermRef fresh_body = rename_term(
287	                        sc->body[bi - 1U], env->clause_arena, env, &rm, env->atoms);
288	                    if (fresh_body == TERM_REF_INVALID ||
289	                        gs_push(&gs, fresh_body) < 0) {
290	                        trail_undo(&env->trail, env->vars, mark);
291	                        goto backtrack;
292	                    }
293	                }
294	            }
295	            continue;
296	        }
297	    }
298	    return solutions;
299	}
