108	                        &query_vars, &clause_vars, &atoms, &db);
109	
110	        bool fired = false;
111	        auto wrapper_cb = [&](SolverEnv *e, const TermRef *, uint32_t, void *) {
112	            if (!fired) { fired = true; cb(*e); }
113	            return SOLVE_STOP;
114	        };
115	
116	        solve(&env, pq.goals, pq.goal_count,
117	              [](SolverEnv *e, const TermRef *g, uint32_t gc, void *ud) {
118	                  return (*static_cast<decltype(wrapper_cb)*>(ud))(e, g, gc, nullptr);
119	              }, &wrapper_cb);
120	        return fired;
121	    }
122	};
