1	/*
2	 * test_framework.hpp — Minimal single-header test runner for Epilog.
3	 *
4	 * No external dependencies. Compile each test_*.cpp independently and run it.
5	 * A non-zero exit code means at least one test failed.
6	 *
7	 * Usage:
8	 *   TEST("description") { EXPECT(...); REQUIRE(...); }
9	 *   int main() { return epilog_test::run_all(); }
10	 *
11	 * Macros:
12	 *   EXPECT(expr)        — record failure if expr is false; continue test
13	 *   EXPECT_EQ(a, b)     — record failure if a != b; print both values
14	 *   EXPECT_NE(a, b)     — record failure if a == b
15	 *   EXPECT_NULL(p)      — record failure if p != nullptr
16	 *   EXPECT_NOTNULL(p)   — record failure if p == nullptr
17	 *   REQUIRE(expr)       — abort current test immediately if expr is false
18	 *   TEST(name)          — declare a test case (registers automatically)
19	 */
20	
21	#pragma once
22	
23	#include <cstdio>
24	#include <cstring>
25	#include <functional>
26	#include <vector>
27	#include <string>
28	
29	namespace epilog_test {
30	
31	struct Result {
32	    bool        passed;
33	    std::string name;
34	    std::string failure_msg;
35	};
36	
37	struct Registry {
38	    struct Entry { std::string name; std::function<void()> fn; };
39	    std::vector<Entry>  entries;
40	    std::vector<Result> results;
41	    int                 failures = 0;
42	
43	    static Registry &get() { static Registry r; return r; }
44	
45	    void add(std::string name, std::function<void()> fn) {
46	        entries.push_back({ std::move(name), std::move(fn) });
47	    }
48	};
49	
50	/* Thrown to abort a single test on REQUIRE failure. */
51	struct TestAbort { std::string msg; };
52	
53	/* Per-test state (reset for each test). */
54	inline thread_local int  tl_failures    = 0;
55	inline thread_local bool tl_in_test     = false;
56	
57	/* Record a failure inside a running test. */
58	inline void record_failure(const char *file, int line, const char *expr)
59	{
60	    tl_failures++;
61	    fprintf(stderr, "    FAIL  %s:%d  %s\n", file, line, expr);
62	}
63	
64	inline int run_all()
65	{
66	    Registry &reg = Registry::get();
67	    int total   = 0;
68	    int passed  = 0;
69	
70	    for (auto &entry : reg.entries) {
71	        total++;
72	        tl_failures = 0;
73	        tl_in_test  = true;
74	        bool aborted = false;
